type goTypeComparison uint8
const (
 goTypeUnknown goTypeComparison = iota
 goTypeDifferent
 goTypeMatch
)

type goTypeDeclaration struct { spec *ast.TypeSpec; scope *goTypeScope }
type goTypeScope struct {
 imports map[string]string
 declarations map[string][]goTypeDeclaration
 packageID string
 index *goFileImports
}

// Package declarations are loaded only when signature matching needs them.
// Each source file is read once. No compiler importer or network fetch is used.
type goFileImports struct {
 readContent contentReader
 modules goModuleIndex
 filesByDir map[string][]string
 byFile map[string]*goTypeScope
 loaded map[string]bool
 packageDirs map[string]string
}
func newGoFileImports(read contentReader, files []FileRecord, modules goModuleIndex) *goFileImports {
 x:= &goFileImports{readContent:read, modules:modules, filesByDir:map[string][]string{}, byFile:map[string]*goTypeScope{}, loaded:map[string]bool{}, packageDirs:map[string]string{}}
 for _,f:=range files {
  if !strings.EqualFold(filepath.Ext(f.Path),".go") {continue}
  dir:=normalizeRepoDir(filepath.Dir(f.Path))
  x.filesByDir[dir]=append(x.filesByDir[dir],f.Path)
  if importPath,ok:=modules.importPathFor(dir);ok {x.packageDirs[importPath]=dir}
 }
 return x
}
func (x *goFileImports) load(dir string) {
 if x.loaded[dir] {return};x.loaded[dir]=true
 packages:=map[string]map[string][]goTypeDeclaration{}
 for _,file:=range x.filesByDir[dir] {
  content,ok:=x.readContent(file);if !ok {continue}
  parsed,err:=parser.ParseFile(token.NewFileSet(),file,content,parser.SkipObjectResolution)
  if err!=nil {continue} // no identity evidence from malformed source
  declarations:=packages[parsed.Name.Name]
  if declarations==nil {declarations=map[string][]goTypeDeclaration{};packages[parsed.Name.Name]=declarations}
  id:="repo:"+dir+":"+parsed.Name.Name
  if modulePath,ok:=x.modules.importPathFor(dir);ok {id=modulePath}
  scope:=&goTypeScope{imports:map[string]string{},declarations:declarations,packageID:id,index:x}
  x.byFile[file]=scope
  for _,imp:=range parsed.Imports {
   importPath,err:=strconv.Unquote(imp.Path.Value);if err!=nil {continue}
   name:=path.Base(importPath)
   if imp.Name!=nil {name=imp.Name.Name}
   if name=="_" || name=="." {continue} // dot imports need declaration evidence
   if _,exists:=scope.imports[name];exists {scope.imports[name]=""} else {scope.imports[name]=importPath}
  }
  for _,decl:=range parsed.Decls {
   gen,ok:=decl.(*ast.GenDecl);if !ok || gen.Tok!=token.TYPE {continue}
   for _,spec:=range gen.Specs {if typ,ok:=spec.(*ast.TypeSpec);ok {declarations[typ.Name.Name]=append(declarations[typ.Name.Name],goTypeDeclaration{typ,scope})}}
  }
 }
}
func (x *goFileImports) forFile(file string) *goTypeScope {
